const qs = $('Load Questions').all().map(i => i.json).filter(r => r && r.session_id);
const docs = $('Load Current Document').all().map(i => i.json).filter(r => r && r.file_name);
const leads = $('Load Leads').all().map(i => i.json).filter(r => r && r.email);
const CATS = ['Rooms & Suites','Pricing & Rates','Dining & Restaurant','Facilities & Amenities','Spa & Wellness','Check-in & Policies','Location & Transport','Events & Meetings','Guest Services','General'];
const byCat = {};
for (const c of CATS) byCat[c] = { category: c, questions: 0, unanswered: 0 };
const sessions = {};
const today = new Date().toISOString().slice(0, 10);
let unanswered = 0, todayQ = 0;
for (const q of qs) {
  const c = byCat[q.category] ? q.category : 'General';
  byCat[c].questions += 1;
  const ok = q.answered === true || q.answered === 'true';
  if (!ok) { byCat[c].unanswered += 1; unanswered += 1; }
  sessions[q.session_id] = sessions[q.session_id] || { first: q.asked_at, last: q.asked_at, count: 0 };
  const s = sessions[q.session_id];
  s.count += 1;
  if (q.asked_at < s.first) s.first = q.asked_at;
  if (q.asked_at > s.last) s.last = q.asked_at;
  if (String(q.asked_at).slice(0, 10) === today) todayQ += 1;
}
const sessionList = Object.values(sessions);
const days = {};
for (let i = 13; i >= 0; i--) { const d = new Date(Date.now() - i * 86400000).toISOString().slice(0, 10); days[d] = { date: d, questions: 0, sessions: 0 }; }
for (const q of qs) { const d = String(q.asked_at).slice(0, 10); if (days[d]) days[d].questions += 1; }
for (const s of sessionList) { const d = String(s.first).slice(0, 10); if (days[d]) days[d].sessions += 1; }
const recent = qs.slice().sort((a, b) => String(b.asked_at).localeCompare(String(a.asked_at))).slice(0, 15).map(q => ({ question: q.question, category: q.category, answered: q.answered === true || q.answered === 'true', asked_at: q.asked_at }));
const doc = docs.sort((a, b) => String(b.uploaded_at).localeCompare(String(a.uploaded_at)))[0] || null;
return [{ json: {
  totals: {
    sessions: sessionList.length,
    sessionsToday: sessionList.filter(s => String(s.first).slice(0, 10) === today).length,
    questions: qs.length,
    questionsToday: todayQ,
    unanswered,
    answerRate: qs.length ? Math.round(((qs.length - unanswered) / qs.length) * 100) : null,
    avgQuestionsPerSession: sessionList.length ? Math.round((qs.length / sessionList.length) * 10) / 10 : 0,
    contactRequests: leads.length
  },
  categories: Object.values(byCat).sort((a, b) => b.questions - a.questions),
  daily: Object.values(days),
  recentQuestions: recent,
  recentLeads: leads.sort((a, b) => String(b.submitted_at).localeCompare(String(a.submitted_at))).slice(0, 5).map(l => ({ name: l.name, question: l.unanswered_question, submitted_at: l.submitted_at })),
  document: doc ? { fileName: doc.file_name, pages: doc.pages, characters: doc.characters, chunks: doc.chunks, uploadedAt: doc.uploaded_at } : null,
  generatedAt: new Date().toISOString()
}}];
